import type { AppLanguage } from '../../components/planner/types';

/**
 * Task categories — a SECONDARY filter axis for the checklist.
 *
 * The primary structure stays time-based (phases / month buckets generated by
 * checklistGenerator). Category is orthogonal: it groups tasks by *what kind of
 * work* they are (venue, catering, attire…) so couples can filter and see
 * per-category progress, the way Akad's category rail works.
 *
 * NOTE: this is a different concept from `GenerationSource['category']` in
 * checklistGenerator.ts, which means *provenance* ('base' | 'state' | 'scale'…).
 * Do not conflate the two.
 */

export type ChecklistCategoryId =
  | 'keperluan-asas'
  | 'nikah-protokol'
  | 'tempat-venue'
  | 'makanan-katering'
  | 'solekan-pakaian'
  | 'pelamin-dekorasi'
  | 'media-dokumentasi'
  | 'hiburan-aturcara'
  | 'jemputan-logistik';

export type ChecklistCategory = {
  id: ChecklistCategoryId;
  labelMs: string;
  labelEn: string;
  /** Matches a `Vendor.category` value when the category maps to a vendor type. */
  vendorCategory?: string;
  /** Lowercase keywords (matched as whole words) used to auto-classify a task. */
  keywords: string[];
};

