const DEFAULT_CATEGORY: ChecklistCategoryId = 'keperluan-asas';

const CATEGORY_BY_ID = new Map<ChecklistCategoryId, ChecklistCategory>(
  CHECKLIST_CATEGORIES.map((c) => [c.id, c])
);

// Precompile keyword matchers once. Whole-word match so short tokens like "mc"
// or "dj" don't fire inside unrelated words.
const escapeRe = (s: string) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const COMPILED: Array<{ id: ChecklistCategoryId; res: RegExp[] }> = CHECKLIST_CATEGORIES.map((c) => ({
  id: c.id,
  res: c.keywords.map((kw) => new RegExp(`(?:^|[^a-z0-9])${escapeRe(kw)}(?:$|[^a-z0-9])`, 'i'))
}));

/**
 * Classify a task into a category by keyword score. Highest score wins; ties
 * break toward whichever category appears first in CHECKLIST_CATEGORIES. Tasks
 * that match nothing fall back to 'keperluan-asas'.
 */
export function categorizeTask(text: string): ChecklistCategoryId {
  const haystack = ` ${(text || '').toLowerCase()} `;
  let bestId: ChecklistCategoryId = DEFAULT_CATEGORY;
  let bestScore = 0;
  for (const entry of COMPILED) {
    let score = 0;
    for (const re of entry.res) if (re.test(haystack)) score += 1;
    if (score > bestScore) {
      bestScore = score;
      bestId = entry.id;
    }
  }
  return bestId;
}

/**
 * Like categorizeTask but returns null when no keyword matches (score = 0),
 * so callers can distinguish "no match" from "default bucket".
 */
export function tryDetectCategory(text: string): ChecklistCategoryId | null {
  if (!text || text.trim().length < 3) return null;
  const haystack = ` ${text.toLowerCase()} `;
  let bestId: ChecklistCategoryId | null = null;
  let bestScore = 0;
  for (const entry of COMPILED) {
    let score = 0;
    for (const re of entry.res) if (re.test(haystack)) score += 1;
    if (score > bestScore) {
      bestScore = score;
      bestId = entry.id;
    }
  }
  return bestId;
}

export function getCategory(id: string | undefined): ChecklistCategory | undefined {
  return id ? CATEGORY_BY_ID.get(id as ChecklistCategoryId) : undefined;
}

export function getCategoryLabel(id: string | undefined, lang: AppLanguage): string {
  const cat = getCategory(id);
  if (!cat) return '';
  return lang === 'ms' ? cat.labelMs : cat.labelEn;
}
